package dev.industrialtechnology.expansion;
import net.minecraftforge.common.config.Configuration;
public final class ExpansionConfig {
 public static final int[] solar={10,40,160,1280,5120};
 public static boolean mixed=true,charcoal=true,trainChunks=true;public static int maxArray=4096,maxWagons=16,chargeRate=50000,trainCapacity=5000000,transfer=32,chunkLimit=9;public static double daylight=1,rain=.35,thunder=.1,speed=1.2,itemMass=100;
 public static void load(Configuration c){for(int i=0;i<5;i++)solar[i]=c.getInt("tier"+(i+1)+"RFPerTick","solar",solar[i],1,1000000,"Peak RF/t in clear noon sun.");mixed=c.getBoolean("mixedTiers","solar",true,"Allow horizontal mixed-tier arrays.");maxArray=c.getInt("maximumArrayPanels","solar",4096,1,16384,"Larger arrays split into independent components.");daylight=c.getFloat("daylightMultiplier","solar",1,0,1,"Sun generation multiplier (0 to 1).");rain=c.getFloat("rainFactor","solar",.35f,0,1,"Wet-weather multiplier.");thunder=c.getFloat("thunderFactor","solar",.1f,0,1,"Thunderstorm multiplier.");maxWagons=c.getInt("maximumWagons","railway",16,1,32,"Maximum connected vehicles behind an engine.");chargeRate=c.getInt("chargingRFPerTick","railway",50000,1,1000000,"Shared charging station and locomotive input limit.");trainCapacity=c.getInt("electricCapacityRF","railway",5000000,1000,1000000000,"Industrial/ACS capacity; AZ8A has double capacity.");transfer=c.getInt("cargoItemsPerTick","railway",32,1,64,"Station aggregate transfer limit.");speed=c.getFloat("maximumBlocksPerTick","railway",1.2f,.05f,2,"Gameplay speed cap; curves have lower limits.");itemMass=c.getFloat("defaultItemMassKg","railway",100,1,1000,"Mass per cargo item; exact registry overrides in itemMassOverrides.");charcoal=c.getBoolean("highCapacityCharcoal","railway",true,"Charcoal also supports 300 items per logical slot.");trainChunks=c.getBoolean("activeTrainChunkLoading","railway",true,"Bounded entity ticket near active consists, never entire routes.");chunkLimit=c.getInt("maximumChunksPerTrain","railway",9,1,25,"Stop safely when the consist cannot fit the granted loaded region.");String[] entries=c.getStringList("itemMassOverrides","railway",new String[]{"minecraft:coal=80","minecraft:iron_ingot=180","minecraft:gold_ingot=200"},"Exact registry name=kg per item. No name guessing.");dev.industrialtechnology.railway.CargoMass.configure(entries);}
}
